## Step 1 -- Set up the shared fixture

```typescript
// test/EmberStake.test.ts
import { expect } from "chai";
import { ethers } from "hardhat";
import { loadFixture } from "@nomicfoundation/hardhat-network-helpers";

describe("EmberStake", () => {
  async function deployFixture() {
    const [owner, feeCollector, alice, bob] = await ethers.getSigners();

    const EmberToken = await ethers.getContractFactory("EmberToken");
    const emberToken = await EmberToken.deploy(ethers.parseEther("1000000"));

    const EmberStake = await ethers.getContractFactory("EmberStake");
    const emberStake = await EmberStake.deploy(await emberToken.getAddress());
    await emberStake.setFeeCollector(feeCollector.address);

    for (const user of [alice, bob]) {
      await emberToken.transfer(user.address, ethers.parseEther("1000"));
      await emberToken.connect(user).approve(await emberStake.getAddress(), ethers.parseEther("1000"));
    }

    return { emberStake, emberToken, owner, feeCollector, alice, bob };
  }
