```

## Step 2 -- Staking and withdrawing

```typescript
  describe("Staking", () => {
    it("lets a user stake EMBER and updates balances", async () => {
      const { emberStake, alice } = await loadFixture(deployFixture);
      await emberStake.connect(alice).stake(ethers.parseEther("100"));
      expect(await emberStake.stakedBalance(alice.address)).to.equal(ethers.parseEther("100"));
      expect(await emberStake.totalStaked()).to.equal(ethers.parseEther("100"));
    });

    it("reverts when staking zero", async () => {
      const { emberStake, alice } = await loadFixture(deployFixture);
      await expect(emberStake.connect(alice).stake(0)).to.be.revertedWith("EmberStake: zero amount");
    });
  });

  describe("Withdrawing", () => {
    it("lets a user withdraw staked EMBER and updates balances", async () => {
      const { emberStake, alice } = await loadFixture(deployFixture);
      await emberStake.connect(alice).stake(ethers.parseEther("100"));
      await emberStake.connect(alice).withdraw(ethers.parseEther("40"));
      expect(await emberStake.stakedBalance(alice.address)).to.equal(ethers.parseEther("60"));
      expect(await emberStake.totalStaked()).to.equal(ethers.parseEther("60"));
    });

    it("reverts when withdrawing more than the caller has staked", async () => {
      const { emberStake, alice } = await loadFixture(deployFixture);
      await emberStake.connect(alice).stake(ethers.parseEther("50"));
      await expect(
        emberStake.connect(alice).withdraw(ethers.parseEther("51"))
      ).to.be.revertedWith("EmberStake: insufficient staked balance");
    });
  });
```

Desmond deliberately keeps every one of these scenarios anchored to Alice and Bob -- two ordinary Hardhat signers backed by plain private keys, with no contract code deployed at either address. That matches how essentially every real EmberStake user will actually interact with the protocol, and it's the fastest, most direct way to validate that the core accounting is correct before worrying about anything more exotic.

## Step 3 -- Reward distribution

```typescript
  describe("Reward distribution", () => {
    it("credits rewardBalance proportionally to stake", async () => {
      const { emberStake, feeCollector, alice, bob } = await loadFixture(deployFixture);
      await emberStake.connect(alice).stake(ethers.parseEther("600"));
      await emberStake.connect(bob).stake(ethers.parseEther("400"));

      await emberStake.connect(feeCollector).distributeRewards(
        [alice.address, bob.address],
        { value: ethers.parseEther("1") }
      );

      expect(await emberStake.rewardBalance(alice.address)).to.equal(ethers.parseEther("0.6"));
      expect(await emberStake.rewardBalance(bob.address)).to.equal(ethers.parseEther("0.4"));
    });

    it("reverts distributeRewards from a non-fee-collector address", async () => {
      const { emberStake, alice } = await loadFixture(deployFixture);
      await expect(
        emberStake.connect(alice).distributeRewards([alice.address], { value: ethers.parseEther("1") })
      ).to.be.revertedWith("EmberStake: not fee collector");
    });
  });
```

## Step 4 -- Claiming rewards

```typescript
  describe("Claiming rewards", () => {
    it("lets a normal user claim their full reward balance", async () => {
      const { emberStake, feeCollector, alice } = await loadFixture(deployFixture);
      await emberStake.connect(alice).stake(ethers.parseEther("100"));
      await emberStake.connect(feeCollector).distributeRewards([alice.address], { value: ethers.parseEther("1") });

      const before = await ethers.provider.getBalance(alice.address);
      const tx = await emberStake.connect(alice).claimRewards();
      const receipt = await tx.wait();
      const gasCost = receipt!.gasUsed * receipt!.gasPrice;
      const after = await ethers.provider.getBalance(alice.address);

      expect(after + gasCost - before).to.equal(ethers.parseEther("1"));
      expect(await emberStake.rewardBalance(alice.address)).to.equal(0);
    });

    it("reverts when a user with no rewards tries to claim", async () => {
      const { emberStake, alice } = await loadFixture(deployFixture);
      await expect(emberStake.connect(alice).claimRewards()).to.be.revertedWith("No rewards to claim");
    });
  });
});
```

