## Step 3 -- Backfill history, then listen live

```typescript
// src/indexer.ts
import { ethers } from "ethers";
import { db } from "./db";
import emberStakeAbi from "./abi/EmberStake.json";

const provider = new ethers.JsonRpcProvider(process.env.RPC_URL);
const emberStake = new ethers.Contract(process.env.CONTRACT_ADDRESS!, emberStakeAbi, provider);

const insert = db.prepare(`
  INSERT OR IGNORE INTO events (tx_hash, log_index, event_name, user_address, amount, block_number)
  VALUES (?, ?, ?, ?, ?, ?)
`);

function recordEvent(name: string, user: string, amount: bigint, log: ethers.Log) {
  insert.run(log.transactionHash, log.index, name, user, amount.toString(), log.blockNumber);
}

async function backfill(fromBlock: number) {
  const latest = await provider.getBlockNumber();
  for (const name of ["Staked", "Withdrawn", "RewardsClaimed"]) {
    const logs = await emberStake.queryFilter(emberStake.getEvent(name), fromBlock, latest);
    for (const log of logs) {
      const [user, amount] = (log as ethers.EventLog).args;
      recordEvent(name, user, amount, log);
    }
  }
}

emberStake.on("Staked", (user, amount, event) => recordEvent("Staked", user, amount, event.log));
emberStake.on("Withdrawn", (user, amount, event) => recordEvent("Withdrawn", user, amount, event.log));
emberStake.on("RewardsClaimed", (user, amount, event) => recordEvent("RewardsClaimed", user, amount, event.log));

backfill(Number(process.env.DEPLOY_BLOCK ?? 0));
```

## Step 4 -- Build the REST API

```typescript
// src/api.ts
import express from "express";
import { db } from "./db";
import { ethers } from "ethers";
import emberStakeAbi from "./abi/EmberStake.json";

const app = express();
const provider = new ethers.JsonRpcProvider(process.env.RPC_URL);
const emberStake = new ethers.Contract(process.env.CONTRACT_ADDRESS!, emberStakeAbi, provider);

function netStakeFor(address?: string) {
