## Step 1 -- Fix 1: reorder effects before interactions

Desmond moves the state write before the external call, so a re-entrant call reads a zeroed balance:

```solidity
// BEFORE -- the vulnerable version Naomi exploited
function claimRewards() external {
    uint256 amount = rewardBalance[msg.sender];
    require(amount > 0, "No rewards to claim");
    (bool success, ) = msg.sender.call{value: amount}("");
    require(success, "Transfer failed");
    rewardBalance[msg.sender] = 0; // effect happens AFTER interaction
}

// AFTER -- effects before interactions
function claimRewards() external nonReentrant {
    uint256 amount = rewardBalance[msg.sender];
    require(amount > 0, "No rewards to claim");
    rewardBalance[msg.sender] = 0; // effect happens BEFORE interaction
    (bool success, ) = msg.sender.call{value: amount}("");
    require(success, "Transfer failed");
}
```

## Step 2 -- Fix 2: add OpenZeppelin's ReentrancyGuard as defense-in-depth

```solidity
// contracts/EmberStake.sol
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract EmberStake is ReentrancyGuard {
    mapping(address => uint256) public rewardBalance;

    function claimRewards() external nonReentrant {
        uint256 amount = rewardBalance[msg.sender];
        require(amount > 0, "No rewards to claim");
        rewardBalance[msg.sender] = 0;
        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Transfer failed");
    }
}
```

The guard reverts any nested call into a `nonReentrant` function on this contract, independent of ordering inside the function -- so a future mistake elsewhere is still caught even if the reordering discipline above ever slips.

